package com.cameronamer.telegramdrive

import android.os.Bundle
import android.os.Handler
import android.os.Looper

/**
 * Tauri entry point, extended with the photo-gallery auto-sync wiring:
 *
 *  1. [MediaSyncScheduler.schedulePeriodic] — a 6-hour WorkManager job that
 *     drains the Rust pending-upload queue (unmetered + charging only).
 *  2. [MediaStoreObserver] — a ContentObserver that feeds newly created or
 *     modified MediaStore URIs straight into the Rust ingestion queue.
 *
 * `TauriActivity` is generated by `tauri build` into this same package
 * (`src/main/generated/TauriActivity.kt`), so no import is required.
 */
class MainActivity : TauriActivity() {

    private val handler = Handler(Looper.getMainLooper())
    private var mediaObserver: MediaStoreObserver? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Idempotent: enqueueUniquePeriodicWork(KEEP) leaves an existing job
        // untouched across process restarts.
        MediaSyncScheduler.schedulePeriodic(this)

        mediaObserver = MediaStoreObserver(this, handler).also { it.register() }
    }

    override fun onDestroy() {
        mediaObserver?.unregister()
        mediaObserver = null
        super.onDestroy()
    }
}
